const list=v=>Array.isArray(v)?v:[];
const defFor=value=>{if(!value)return null;if(typeof value==='object'&&value.id&&byId.has(value.id))return byId.get(value.id);const raw=typeof value==='string'?value:(value.id||value.label||value.badge||'');return byId.get(raw)||byName.get(String(raw).toLowerCase())||null};

function normalizeEntry(value){
  const def=defFor(value);if(!def)return null;
  const src=typeof value==='object'&&value?value:{};
  const grantIds=[...new Set(list(src.grantIds||src.auditIds).map(String).filter(Boolean))];
  return {id:def.id,label:def.name,count:Math.max(1,Number(src.count)||grantIds.length||1),grantIds,grantedAt:String(src.grantedAt||src.earnedAt||new Date().toISOString()),lastGrantedAt:String(src.lastGrantedAt||src.grantedAt||src.earnedAt||new Date().toISOString()),source:String(src.source||src.method||'Legacy LotKeys award'),storeName:String(src.storeName||''),approvedBy:String(src.approvedBy||''),reason:String(src.reason||'')};
}
function entriesFrom(value){const rows=Array.isArray(value)?value:list(value?.awards||value?.unlockedBadges);return rows.map(normalizeEntry).filter(Boolean)}
function mergeEntries(...collections){const map=new Map();for(const rows of collections)for(const raw of entriesFrom(rows)){const old=map.get(raw.id);if(!old){map.set(raw.id,raw);continue}const ids=[...new Set([...old.grantIds,...raw.grantIds])],count=Math.max(old.count,raw.count,ids.length||0);map.set(raw.id,{...old,...raw,grantedAt:[old.grantedAt,raw.grantedAt].filter(Boolean).sort()[0]||raw.grantedAt,lastGrantedAt:[old.lastGrantedAt,raw.lastGrantedAt].filter(Boolean).sort().slice(-1)[0]||raw.lastGrantedAt,grantIds:ids,count})}return [...map.values()].sort((a,b)=>Date.parse(b.lastGrantedAt||0)-Date.parse(a.lastGrantedAt||0))}
function grantEntry(rows,awardId,auditId,meta={}){const def=byId.get(awardId);if(!def)return {rows:entriesFrom(rows),changed:false};const next=entriesFrom(rows),i=next.findIndex(x=>x.id===awardId),stamp=meta.grantedAt||new Date().toISOString(),audit=String(auditId||uid('GRANT'));if(i>=0){const entry=next[i];if(entry.grantIds.includes(audit)||!def.repeatable)return {rows:next,changed:false};entry.grantIds=[...entry.grantIds,audit];entry.count=Math.max(entry.count+1,entry.grantIds.length);entry.lastGrantedAt=stamp;entry.source=meta.source||entry.source;entry.approvedBy=meta.approvedBy||entry.approvedBy;entry.reason=meta.reason||entry.reason;entry.storeName=meta.storeName||entry.storeName;return {rows:next,changed:true}}next.unshift({id:def.id,label:def.name,count:1,grantIds:[audit],grantedAt:stamp,lastGrantedAt:stamp,source:String(meta.source||def.method),storeName:String(meta.storeName||''),approvedBy:String(meta.approvedBy||''),reason:String(meta.reason||'')});return {rows:next,changed:true}}
function removeEntry(rows,awardId){const before=entriesFrom(rows),after=before.filter(x=>x.id!==awardId);return {rows:after,changed:after.length!==before.length}}
function awardSummary(rows){return entriesFrom(rows).map(x=>({id:x.id,label:x.label,count:x.count,grantIds:x.grantIds,grantedAt:x.grantedAt,lastGrantedAt:x.lastGrantedAt,source:x.source,storeName:x.storeName,approvedBy:x.approvedBy,reason:x.reason}))}

function levelThreshold(level){level=Math.max(1,Math.min(100,Number(level)||1));if(level<=1)return 0;if(level>=100)return 1000;return Math.max(1,Math.ceil(1000*Math.pow((level-1)/99,1.75)))}
function levelForPosts(posts){posts=Math.max(0,Number(posts)||0);if(posts>=1000)return 100;let level=1;for(let n=2;n<=100;n++){if(posts<levelThreshold(n))break;level=n}return level}
function progressState(raw={}){const confirmed=list(raw?.confirmedPosts).filter(x=>x&&x.key),sales=list(raw?.vehicleSales).filter(x=>x&&x.key),facebookSales=sales.filter(x=>x.facebookQualified===true||validFacebookUrl(x.facebookUrl));const level=levelForPosts(confirmed.length);return {schemaVersion:2,confirmedPosts:confirmed.slice(-1500),confirmedPostCount:confirmed.length,vehicleSales:sales.slice(-1500),vehicleSaleCount:sales.length,confirmedFacebookSaleCount:facebookSales.length,level,curve:'progressive-1.75-test',level100Posts:1000,updatedAt:String(raw?.updatedAt||new Date().toISOString())}}
function facebookPostKey(data={},storeId=''){const listing=String(data.listingId||'').trim();if(listing)return `${storeId||'store'}:${listing}`;try{const u=new URL(String(data.facebookUrl||''));return `${u.hostname.toLowerCase()}${u.pathname.replace(/\/$/,'')}`}catch{return''}}
function validFacebookUrl(value=''){try{const u=new URL(String(value));return /(^|\.)facebook\.com$/i.test(u.hostname)&&/\/marketplace\//i.test(u.pathname)}catch{return false}}
function localDayKey(value=Date.now()){const d=new Date(value);return Number.isNaN(d.getTime())?'':`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function activityKey(data={},prefix='activity'){const id=String(data.listingId||data.vehicleId||data.id||'').trim();return id?`${prefix}:${id}`:`${prefix}:${String(data.createdAt||data.soldAt||data.deletedAt||Date.now())}`}

function toast(text){const el=document.getElementById('toast');if(el){el.textContent=String(text);el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{el.hidden=true},2600);return}const t=document.createElement('div');t.className='lkaw-toast';t.textContent=String(text);document.body.appendChild(t);setTimeout(()=>t.remove(),2600)}
function closeModal(){const modal=document.getElementById('modal');modal?.classList.remove('public-profile-modal');if(modal?.open)modal.close()}
function openModal(html){const modal=document.getElementById('modal'),body=document.getElementById('modal-body');if(!modal||!body)return null;body.innerHTML=html;body.querySelector('.lkaw-close')?.addEventListener('click',closeModal);if(!modal.open)modal.showModal();return body}
function definitionOptions({includeCreator=false}={}){return CATALOG.filter(x=>includeCreator||!x.creatorOnly).map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${esc(x.method)}</option>`).join('')}
async function currentUser(){const users=list(await get('storeUsers',[])),name=await get('userName',''),email=await get('currentAccountEmail','');return users.find(x=>same(x.userName,name)||(email&&same(x.email,email)))||null}
async function currentAdminLevel(){const user=await currentUser();return Math.max(0,Math.min(2,Number(user?.adminLevel??await get('currentUserAdminLevel',0))||0))}
async function currentIsCreator(){const email=String(await get('currentAccountEmail','')).trim().toLowerCase();return !!email&&list(creatorAccess.creatorGoogleAccounts).map(x=>String(x).trim().toLowerCase()).includes(email)}
async function storeName(){return String(await get('storeName','')||await get('storeFolderName','')||'LotKeys Store')}

let syncTimer=null;
function queueAccountSync(){clearTimeout(syncTimer);syncTimer=setTimeout(async()=>{const b=bridge();if(!b)return;try{await set('personalProfileUpdatedAt',Date.now());const status=await b.DriveSync?.getStatus?.();if(status?.connected){await b.DriveSync.syncPersonalProfile?.().catch(console.warn);await b.DriveSync.syncStoreProfileThumbnail?.().catch(console.warn)}}catch(err){console.warn('Awards Account sync deferred',err)}},700)}
async function storeProfileForCurrent(entries,progress,profile){const b=bridge();if(!b)return false;const users=b.normalizeStoreUsers?b.normalizeStoreUsers(await get('storeUsers',[])):list(await get('storeUsers',[])),name=await get('userName',''),email=await get('currentAccountEmail',''),i=users.findIndex(x=>same(x.userName,name)||(email&&same(x.email,email)));if(i<0)return false;const def=byId.get(profile.primaryAwardId),next={...users[i],awards:awardSummary(entries),unlockedBadges:awardSummary(entries),primaryAwardId:profile.primaryAwardId||'',displayAwardIds:list(profile.displayAwardIds).slice(0,5),favoriteBadge:def?.name||'',lotLevel:progress.level,confirmedFacebookPosts:progress.confirmedPosts.length,lotKeysVehicleSales:progress.vehicleSales.length,confirmedFacebookSales:progress.confirmedFacebookSaleCount,awardProfile:{primaryAwardId:profile.primaryAwardId||'',displayAwardIds:list(profile.displayAwardIds).slice(0,5)}};if(JSON.stringify(users[i])===JSON.stringify(next))return false;users[i]=b.normalizeUserAccount?b.normalizeUserAccount(next):next;await set('storeUsers',users);return true}
async function localProfile(entries=null){entries=entries||entriesFrom(await get('unlockedBadges',[]));const raw=await get(PROFILE_KEY,{}),valid=new Set(entries.map(x=>x.id));let primary=String(raw?.primaryAwardId||'');if(!valid.has(primary)){const legacy=defFor(await get('favoriteBadge',''));primary=legacy&&valid.has(legacy.id)?legacy.id:(entries[0]?.id||'')}let display=list(raw?.displayAwardIds).map(String).filter((x,i,a)=>valid.has(x)&&x!==primary&&a.indexOf(x)===i).slice(0,5);for(const e of entries)if(e.id!==primary&&!display.includes(e.id)&&display.length<5)display.push(e.id);return {schemaVersion:1,primaryAwardId:primary,displayAwardIds:display,updatedAt:String(raw?.updatedAt||new Date().toISOString())}}
async function importCurrentStoreAwards(){const me=await currentUser(),local=entriesFrom(await get('unlockedBadges',[])),remote=entriesFrom(me?.awards?.length?me.awards:me?.unlockedBadges),merged=mergeEntries(local,remote),profile=await localProfile(merged),oldProfile=await get(PROFILE_KEY,{});let changed=JSON.stringify(local)!==JSON.stringify(merged)||JSON.stringify({primaryAwardId:oldProfile?.primaryAwardId||'',displayAwardIds:list(oldProfile?.displayAwardIds)})!==JSON.stringify({primaryAwardId:profile.primaryAwardId,displayAwardIds:profile.displayAwardIds});if(changed){profile.updatedAt=new Date().toISOString();await set('unlockedBadges',awardSummary(merged));await set(PROFILE_KEY,profile);await set('favoriteBadge',byId.get(profile.primaryAwardId)?.name||'');queueAccountSync()}return {entries:merged,profile}}

async function ensureProgressFromListings(){const b=bridge();if(!b?.DB)return progressState(await get(PROGRESS_KEY,{}));const state=progressState(await get(PROGRESS_KEY,{})),seen=new Set(state.confirmedPosts.map(x=>x.key)),storeId=String(await get('storeFolderId','')||'store'),myName=String(await get('userName','')),rows=await b.DB.all('listings'),added=[];for(const row of rows){if(!row?.postedAt||!validFacebookUrl(row.facebookUrl)||row.ownerUserName&&!same(row.ownerUserName,myName))continue;const key=facebookPostKey(row,storeId);if(!key||seen.has(key))continue;seen.add(key);added.push({key,listingId:String(row.id||''),vehicleId:String(row.vehicleId||''),facebookUrl:String(row.facebookUrl||''),postedAt:row.postedAt,confirmedAt:new Date().toISOString(),source:'Existing saved LotKeys Listing'})}if(!added.length)return state;const next=progressState({...state,confirmedPosts:[...state.confirmedPosts,...added],updatedAt:new Date().toISOString()});await set(PROGRESS_KEY,next);const imported=await importCurrentStoreAwards(),profile=imported.profile;await storeProfileForCurrent(imported.entries,next,profile);queueAccountSync();return next}
async function confirmFacebookPost(data={}){try{if(!validFacebookUrl(data.facebookUrl))return false;const myName=String(await get('userName',''));if(data.ownerUserName&&!same(data.ownerUserName,myName))return false;const state=progressState(await get(PROGRESS_KEY,{})),storeId=String(await get('storeFolderId','')||'store'),key=facebookPostKey(data,storeId);if(!key||state.confirmedPosts.some(x=>x.key===key))return false;const previous=state.level;state.confirmedPosts.push({key,listingId:String(data.listingId||''),vehicleId:String(data.vehicleId||''),facebookUrl:String(data.facebookUrl||''),postedAt:data.postedAt||Date.now(),confirmedAt:new Date().toISOString(),source:String(data.source||'LotKeys confirmed Facebook post')});state.updatedAt=new Date().toISOString();const next=progressState(state);await set(PROGRESS_KEY,next);const imported=await importCurrentStoreAwards();await storeProfileForCurrent(imported.entries,next,imported.profile);const vehicle=data.vehicleId?await bridge()?.DB?.get?.('vehicles',data.vehicleId):null;if(Number(data.price||vehicle?.price)>0&&['price-unconfirmed','check-failed'].includes(String(vehicle?.websitePriceFinding?.status||'')))await grantCurrentAutomatic('faster-as-f-boy',`auto:faster:${key}`,'Confirmed Facebook post before a source-site price was available');queueAccountSync();if(next.level>previous)toast(`Lot-Lvl ${next.level} unlocked ⚡`);scheduleDecorate();return true}catch(err){console.warn('Lot-Lvl confirmation deferred',err);return false}}

async function recordVehicleProfileCreated(data={}){try{return await grantCurrentAutomatic('new-kid-on-the-lot',`auto:first-profile:${String(data.vehicleId||data.id||'first')}`,'Created a first Vehicle Profile')}catch(err){console.warn('New Kid on the Lot award deferred',err);return false}}
async function recordListingCreated(data={}){try{const created=new Date(data.createdAt||Date.now()),hour=created.getHours(),minute=created.getMinutes();if(!([4,16].includes(hour)&&minute>=19&&minute<=21))return false;return await grantCurrentAutomatic('dude-wheres-my-car',`auto:dude:${activityKey(data,'listing')}`,'Created a Listing during the hidden 4:19–4:21 window')}catch(err){console.warn('Dude Where’s My Car award deferred',err);return false}}
async function recordListingDeleted(data={}){try{const website=String(data.websiteUrl||data.facebookUrl||data.originalListingUrl||'').trim();if(!/^https?:\/\//i.test(website))return false;return await grantCurrentAutomatic('anti-celibratory',`auto:anti:${activityKey(data,'listing')}`,'Deleted a website-connected Listing without marking it sold')}catch(err){console.warn('Anti-Celibratory award deferred',err);return false}}
async function recordVehicleSale(data={}){
  try{
    const myName=String(await get('userName','')),myEmail=String(await get('currentAccountEmail',''));if(data.ownerUserName&&!same(data.ownerUserName,myName))return false;
    const state=progressState(await get(PROGRESS_KEY,{})),key=activityKey(data,'sale');if(state.vehicleSales.some(x=>x.key===key))return false;
    const soldAt=data.soldAt||Date.now(),facebookQualified=validFacebookUrl(data.facebookUrl),row={key,listingId:String(data.listingId||data.id||''),vehicleId:String(data.vehicleId||''),facebookUrl:String(data.facebookUrl||''),facebookQualified,soldAt,dayKey:localDayKey(soldAt),source:'I Sold This Vehicle'};
    state.vehicleSales.push(row);state.updatedAt=new Date().toISOString();const next=progressState(state);await set(PROGRESS_KEY,next);
    const milestones=[[1,'woop-woop'],[10,'mr-sales-man'],[50,'sales-50'],[100,'sales-100'],[250,'quarter-k-club'],[500,'sales-500'],[1000,'sales-1000']];for(const [count,awardId] of milestones)if(next.confirmedFacebookSaleCount>=count)await grantCurrentAutomatic(awardId,`auto:facebook-sales:${count}`,`${count} unique LotKeys-assisted Facebook vehicle sale${count===1?'':'s'}`);
    const sameDay=next.vehicleSales.filter(x=>x.dayKey===row.dayKey);if(sameDay.length>=2&&myName){const nominations=list(await get(NOMINATIONS_KEY,[])),id=`auto:cherrys:${row.dayKey}:${(myEmail||myName).toLowerCase()}`;if(!nominations.some(x=>x.id===id)){nominations.push({id,kind:'automatic-admin-review',status:'pending',awardId:'cherrys',targetUserName:myName,requestedByUserName:'LotKeys',reason:`Two vehicle sales recorded on ${row.dayKey}.`,createdAt:new Date().toISOString()});await set(NOMINATIONS_KEY,nominations);await bridge()?.DriveSync?.syncStoreConfig?.().catch(err=>console.warn('Cherry’s review will sync later',err));toast('Two sales today — Cherry’s sent for Admin review 🍒')}}
    const imported=await importCurrentStoreAwards();await storeProfileForCurrent(imported.entries,next,imported.profile);queueAccountSync();scheduleDecorate();return true;
  }catch(err){console.warn('Vehicle sale award tracking deferred',err);return false}
}

async function grantCurrentAutomatic(awardId,auditId,reason=''){const imported=await importCurrentStoreAwards(),result=grantEntry(imported.entries,awardId,auditId,{source:'Automatic',reason,storeName:await storeName()});if(!result.changed)return false;await set('unlockedBadges',awardSummary(result.rows));const profile=await localProfile(result.rows);await set(PROFILE_KEY,profile);await set('favoriteBadge',byId.get(profile.primaryAwardId)?.name||'');const progress=progressState(await get(PROGRESS_KEY,{}));await storeProfileForCurrent(result.rows,progress,profile);queueAccountSync();return true}
async function removeCurrentAutomatic(awardId){const imported=await importCurrentStoreAwards(),result=removeEntry(imported.entries,awardId);if(!result.changed)return false;await set('unlockedBadges',awardSummary(result.rows));const profile=await localProfile(result.rows);await set(PROFILE_KEY,profile);await set('favoriteBadge',byId.get(profile.primaryAwardId)?.name||'');const progress=progressState(await get(PROGRESS_KEY,{}));await storeProfileForCurrent(result.rows,progress,profile);queueAccountSync();return true}

async function saveStoreUsers(users,{sync=true}={}){const b=bridge();await set('storeUsers',b?.normalizeStoreUsers?b.normalizeStoreUsers(users):users);if(sync)await b?.DriveSync?.syncStoreConfig?.();return users}
function grantUserRecord(user,awardId,auditId,meta={}){const current=entriesFrom(user?.awards?.length?user.awards:user?.unlockedBadges),result=grantEntry(current,awardId,auditId,meta);if(!result.changed)return {user,changed:false};return {user:{...user,awards:awardSummary(result.rows),unlockedBadges:awardSummary(result.rows)},changed:true}}
async function grantStoreAward(userName,awardId,auditId,meta={},sync=true){if(list(creatorAccess.specialAwardIds).includes(String(awardId))&&!await currentIsCreator())throw new Error('Only the registered LotKeys Creator can approve this special Award.');const users=list(await get('storeUsers',[])),i=users.findIndex(x=>same(x.userName,userName));if(i<0)throw new Error('That LotKeys Store user could not be found.');const result=grantUserRecord(users[i],awardId,auditId,{...meta,storeName:meta.storeName||await storeName()});if(!result.changed)return false;users[i]=result.user;await saveStoreUsers(users,{sync});if(same(userName,await get('userName','')))await importCurrentStoreAwards();return true}

async function recordApprovedProfileCorrection(userName,requestId){try{if(!userName||!requestId)return false;const users=list(await get('storeUsers',[])),i=users.findIndex(x=>same(x.userName,userName));if(i<0)return false;const stats=users[i].awardStats&&typeof users[i].awardStats==='object'?{...users[i].awardStats}:{},ids=[...new Set(list(stats.approvedProfileCorrectionIds).map(String))];if(ids.includes(String(requestId)))return false;ids.push(String(requestId));stats.approvedProfileCorrectionIds=ids.slice(-500);stats.approvedProfileCorrections=ids.length;users[i]={...users[i],awardStats:stats};let changed=true;if(ids.length>=10){const r=grantUserRecord(users[i],'detail-detective','auto:profile-corrections:10',{source:'Automatic',reason:'10 approved Vehicle Profile correction requests',storeName:await storeName()});users[i]=r.user;changed=changed||r.changed}if(ids.length>=100){const r=grantUserRecord(users[i],'folder-freak','auto:profile-corrections:100',{source:'Automatic',reason:'100 approved Vehicle Profile correction requests',storeName:await storeName()});users[i]=r.user;changed=changed||r.changed}if(changed){await saveStoreUsers(users);if(same(userName,await get('userName','')))await importCurrentStoreAwards()}scheduleDecorate();return true}catch(err){console.warn('Profile-correction award deferred',err);return false}}

function standingRows(snapshot={}){return list(snapshot.standings).filter(x=>Number(x.points)>0).slice().sort((a,b)=>(Number(a.placement)||999)-(Number(b.placement)||999)||Number(b.points)-Number(a.points))}
async function applyAutomaticStoreAwards(){
  try{
    if(await currentAdminLevel()<1)return false;
    const history=list(await get('monthlyContributionHistory',[])).filter(x=>x?.monthKey&&Array.isArray(x.standings)).slice().sort((a,b)=>(Number(a.monthStart)||Date.parse(a.monthKey)||0)-(Number(b.monthStart)||Date.parse(b.monthKey)||0));
    const users=list(await get('storeUsers',[]));
    if(!history.length||!users.length)return false;
    const activeStoreName=await storeName(),winRuns=new Map(),lastCounts=new Map();
    let changed=false;
    const give=(user,awardId,auditId)=>grantUserRecord(user,awardId,auditId,{source:'Automatic Monthly Wrap-Up',storeName:activeStoreName});
    for(const snap of history){
      const rows=standingRows(snap);
      if(!rows.length)continue;
      const placements=new Map(rows.map((r,i)=>[String(r.userName||'').toLowerCase(),Number(r.placement)||i+1]));
      const lastName=String(rows[rows.length-1].userName||'');
      for(let i=0;i<users.length;i++){
        const name=String(users[i].userName||''),key=name.toLowerCase(),place=placements.get(key)||0;
        const grant=(awardId,auditId)=>{const result=give(users[i],awardId,auditId);users[i]=result.user;changed=changed||result.changed};
        if(place===1){grant('gold-medal',`auto:gold:${snap.monthKey}`);grant('big-number-1',`auto:first:${snap.monthKey}`)}
        else if(place===2){grant('silver-medal',`auto:silver:${snap.monthKey}`);grant('big-runner-up',`auto:second:${snap.monthKey}`)}
        else if(place===3){grant('bronze-medal',`auto:bronze:${snap.monthKey}`);grant('runner-up-to-runner-up',`auto:third:${snap.monthKey}`)}
        if(place&&place>Math.max(0,rows.length-3))grant('you-did-a-thing',`auto:bottom-three:${snap.monthKey}`);
        const wins=place===1?(winRuns.get(key)||0)+1:0;
        winRuns.set(key,wins);
        if(wins>=5)grant('true-achiever',`auto:five-wins:${snap.monthKey}`);
        if(wins>=10)grant('mr-over-achiever',`auto:ten-wins:${snap.monthKey}`);
        const lastCount=(lastCounts.get(key)||0)+(same(name,lastName)?1:0);
        lastCounts.set(key,lastCount);
        if(lastCount>=3)grant('ice-trophy','auto:last-place:three');
      }
    }
    if(changed){await saveStoreUsers(users);await importCurrentStoreAwards();scheduleDecorate()}
    return changed;
  }catch(err){console.warn('Automatic Store awards deferred',err);return false}
}

async function processCheckIn(){try{const raw=await get(CHECKIN_KEY,{}),now=new Date(),today=Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate()),last=Date.parse(raw?.lastCheckInAt||0)||0,lastDay=last?Date.UTC(new Date(last).getUTCFullYear(),new Date(last).getUTCMonth(),new Date(last).getUTCDate()):0,accountCreated=Date.parse(await get('accountCreatedAt',''))||0,returnedAfter30=!!(last&&accountCreated&&Date.now()-last>=30*86400000);let inactiveAwardActive=raw?.inactiveAwardActive===true||returnedAfter30;if(returnedAfter30)await grantCurrentAutomatic('iced-iced-baby',`auto:inactive:${today}`,'Returned after 30 days away');else if(!inactiveAwardActive)await removeCurrentAutomatic('iced-iced-baby');let streak=Number(raw?.consecutiveDays)||0;if(lastDay===today)return;if(lastDay===today-86400000)streak+=1;else streak=1;if(inactiveAwardActive&&streak>=5){await removeCurrentAutomatic('iced-iced-baby');inactiveAwardActive=false}await set(CHECKIN_KEY,{schemaVersion:2,lastCheckInAt:new Date().toISOString(),consecutiveDays:streak,inactiveAwardActive,updatedAt:new Date().toISOString()});queueAccountSync()}catch(err){console.warn('Award check-in tracking deferred',err)}}

function countLabel(entry){const def=byId.get(entry.id),count=Math.max(1,Number(entry?.count)||1);return def?.repeatable?(count>=100?'99+':String(count)):''}
function badgeButton(entry,{large=false,primary=false,reorder=false}={}){const def=byId.get(entry.id);if(!def)return'';const count=countLabel(entry);return `<button class="lkaw-badge ${large?'large':''} ${primary?'primary':''} ${reorder?'lkaw-reorder-badge':''}" type="button" data-lkaw-id="${esc(entry.id)}" ${reorder?'data-lkaw-reorder="1" draggable="false"':''} title="${esc(def.name)}" aria-label="${esc(def.name)}${count?`, received ${entry.count} times`:''}"><span class="lkaw-art"><img src="${esc(def.image)}" alt="" draggable="false">${count?`<b>${esc(count)}</b>`:''}${reorder?'<i class="lkaw-reorder-cue" aria-hidden="true">↕</i>':''}</span><span>${esc(def.name)}</span></button>`}
function emptyBadge(){return '<span class="lkaw-empty-badge"><i>＋</i><small>Open slot</small></span>'}
function bindBadgeButtons(root,entries){root?.querySelectorAll?.('[data-lkaw-id]:not([data-lkaw-reorder])').forEach(btn=>{let timer=null;btn.addEventListener('contextmenu',e=>e.preventDefault());btn.addEventListener('pointerdown',()=>{timer=setTimeout(()=>showAwardName(btn,byId.get(btn.dataset.lkawId)?.name||'LotKeys Award'),550)});['pointerup','pointercancel','pointerleave'].forEach(ev=>btn.addEventListener(ev,()=>clearTimeout(timer)));btn.addEventListener('click',()=>showAwardDetails(btn.dataset.lkawId,entries.find(x=>x.id===btn.dataset.lkawId)))})}
function showAwardName(btn,name){document.querySelector('.lkaw-name-tip')?.remove();const tip=document.createElement('div');tip.className='lkaw-name-tip';tip.textContent=name;document.body.appendChild(tip);const r=btn.getBoundingClientRect();tip.style.left=`${Math.max(8,Math.min(innerWidth-tip.offsetWidth-8,r.left+r.width/2-tip.offsetWidth/2))}px`;tip.style.top=`${Math.max(8,r.top-tip.offsetHeight-8)}px`;setTimeout(()=>tip.remove(),1300)}
function showAwardDetails(id,entry){const def=byId.get(id);if(!def)return;const total=def.repeatable||Number(entry?.count)>1?`<div class="lkaw-total">Total received: ${Math.max(1,Number(entry?.count)||1)}</div>`:'';openModal(`<div class="modal-head"><div><div class="eyebrow">LOTKEYS AWARD</div><h2>${esc(def.name)}</h2></div><button class="close lkaw-close">×</button></div><div class="lkaw-detail"><img src="${esc(def.image)}" alt="${esc(def.name)}"><p>${esc(def.meaning)}</p>${total}<small>Earned ${entry?.lastGrantedAt?esc(new Date(entry.lastGrantedAt).toLocaleDateString('en-CA')):'through LotKeys'}</small></div>`)}

async function renderProfileCard(){const main=document.getElementById('main'),identity=main?.querySelector('.profile-identity-card');if(!identity||document.getElementById('lkaw-profile-card'))return;const imported=await importCurrentStoreAwards(),progress=await ensureProgressFromListings(),entries=imported.entries,profile=await localProfile(entries),primary=entries.find(x=>x.id===profile.primaryAwardId),display=profile.displayAwardIds.map(id=>entries.find(x=>x.id===id)).filter(Boolean).slice(0,5),level=progress.level,currentAt=levelThreshold(level),nextAt=level>=100?1000:levelThreshold(level+1),pct=level>=100?100:Math.max(0,Math.min(100,Math.round(100*(progress.confirmedPosts.length-currentAt)/Math.max(1,nextAt-currentAt)))),remaining=Math.max(0,nextAt-progress.confirmedPosts.length);const card=document.createElement('div');card.className='card lkaw-profile-card';card.id='lkaw-profile-card';card.innerHTML=`<div class="lkaw-title"><div><div class="eyebrow">LOTKEYS AWARDS</div><h2>Lot-Lvl ${level}</h2></div><strong>${progress.confirmedPosts.length.toLocaleString('en-CA')} / 1,000</strong></div><div class="lkaw-level-track"><i style="width:${pct}%"></i></div><div class="lkaw-level-note">${level>=100?'Maximum Lot-Lvl reached ⚡':`${remaining} more confirmed Facebook vehicle post${remaining===1?'':'s'} to Lot-Lvl ${level+1}`}</div><div class="lkaw-showcase"><div class="lkaw-primary"><small>Primary Award</small>${primary?badgeButton(primary,{large:true,primary:true}):emptyBadge()}</div><div class="lkaw-five"><small>Five Displayed Awards</small><div>${[0,1,2,3,4].map(i=>display[i]?badgeButton(display[i]):emptyBadge()).join('')}</div></div></div><div class="actions lkaw-actions"><button class="btn" id="lkaw-customize" type="button" ${entries.length?'':'disabled'}>Choose Display</button><button class="btn ghost" id="lkaw-view-all" type="button" ${entries.length?'':'disabled'}>View All User Awards</button><button class="btn primary" id="lkaw-request" type="button">Request an Award</button></div><div class="help">Awards and Lot-Lvl stay with your personal LotKeys Account when you change Stores. The current test curve reaches Level 100 at 1,000 confirmed Facebook vehicle posts.</div>`;identity.after(card);identity.querySelector('#favorite-badge')?.closest?.('.field')?.setAttribute('hidden','');card.querySelector('#lkaw-customize')?.addEventListener('click',()=>showDisplayManager(entries,profile));card.querySelector('#lkaw-view-all')?.addEventListener('click',()=>showAllAwards(entries));card.querySelector('#lkaw-request')?.addEventListener('click',showAwardRequest);bindBadgeButtons(card,entries);decorateInlinePrimary(document)}

function showAllAwards(entries){const body=openModal(`<div class="modal-head"><div><div class="eyebrow">MY LOTKEYS ACCOUNT</div><h2>All User Awards</h2></div><button class="close lkaw-close">×</button></div><div class="lkaw-all-grid">${entries.length?entries.map(x=>badgeButton(x)).join(''):'<div class="empty">No awards earned yet.</div>'}</div>`);bindBadgeButtons(body,entries)}
function showDisplayManager(entries,profile){
  const rows=entries.map(e=>{const def=byId.get(e.id);return `<div class="lkaw-picker-row"><img src="${esc(def.image)}" alt=""><span><strong>${esc(def.name)}</strong><small>${esc(def.meaning)}</small></span><label><input type="radio" name="lkaw-primary-choice" value="${esc(e.id)}" ${profile.primaryAwardId===e.id?'checked':''}> Primary</label><label><input type="checkbox" data-lkaw-display-choice value="${esc(e.id)}" ${profile.displayAwardIds.includes(e.id)?'checked':''}> Display</label></div>`}).join('');
  const body=openModal(`<div class="modal-head"><div><div class="eyebrow">MY LOTKEYS ACCOUNT</div><h2>Choose Displayed Awards</h2></div><button class="close lkaw-close">×</button></div><div class="help">Choose one Primary Award and up to five additional awards. Drag any displayed badge itself to change the order.</div><div class="lkaw-display-order"><small>DISPLAY ORDER</small><div id="lkaw-order-strip"></div></div><div class="lkaw-picker-list">${rows}</div><button class="btn primary block" id="lkaw-save-display" type="button">Save Award Display</button>`);
  let order=list(profile.displayAwardIds).filter(id=>entries.some(e=>e.id===id)).slice(0,5),drag=null;
  const selected=()=>[...body.querySelectorAll('[data-lkaw-display-choice]:checked')].map(x=>x.value);
  const renderOrder=()=>{const chosen=selected();order=order.filter(id=>chosen.includes(id));for(const id of chosen)if(!order.includes(id)&&order.length<5)order.push(id);const strip=body.querySelector('#lkaw-order-strip');strip.innerHTML=order.map(id=>badgeButton(entries.find(e=>e.id===id),{reorder:true})).join('')||'<div class="help">Choose Display on up to five awards.</div>';strip.querySelectorAll('[data-lkaw-reorder]').forEach(btn=>{btn.addEventListener('contextmenu',e=>e.preventDefault());btn.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;drag={id:btn.dataset.lkawId,pointerId:e.pointerId};btn.setPointerCapture?.(e.pointerId);btn.classList.add('dragging');e.preventDefault()});btn.addEventListener('pointermove',e=>{if(!drag||drag.pointerId!==e.pointerId)return;const over=document.elementFromPoint(e.clientX,e.clientY)?.closest?.('[data-lkaw-reorder]');if(!over||over===btn)return;const from=order.indexOf(drag.id),to=order.indexOf(over.dataset.lkawId);if(from<0||to<0)return;order.splice(to,0,order.splice(from,1)[0]);if(to>from)strip.insertBefore(btn,over.nextSibling);else strip.insertBefore(btn,over)});const end=e=>{if(!drag||drag.pointerId!==e.pointerId)return;drag=null;btn.classList.remove('dragging')};btn.addEventListener('pointerup',end);btn.addEventListener('pointercancel',end)});};
  body.querySelectorAll('[data-lkaw-display-choice]').forEach(x=>x.addEventListener('change',()=>{const checked=selected();if(checked.length>5){x.checked=false;toast('Choose up to five displayed awards.')}renderOrder()}));
  body.querySelectorAll('[name="lkaw-primary-choice"]').forEach(x=>x.addEventListener('change',()=>{const duplicate=body.querySelector(`[data-lkaw-display-choice][value="${CSS.escape(x.value)}"]`);if(duplicate?.checked){duplicate.checked=false;order=order.filter(id=>id!==x.value);renderOrder()}}));
  renderOrder();
  body.querySelector('#lkaw-save-display').onclick=async()=>{const save=body.querySelector('#lkaw-save-display'),primary=String(body.querySelector('[name="lkaw-primary-choice"]:checked')?.value||''),display=order.filter(x=>x!==primary).slice(0,5),next={schemaVersion:1,primaryAwardId:primary,displayAwardIds:display,updatedAt:new Date().toISOString()};save.disabled=true;save.textContent='Saving…';await set(PROFILE_KEY,next);await set('favoriteBadge',byId.get(primary)?.name||'');const progress=progressState(await get(PROGRESS_KEY,{}));await storeProfileForCurrent(entries,progress,next);closeModal();await bridge()?.rerender?.();document.getElementById('lkaw-profile-card')?.remove();await renderProfileCard();decorateInlinePrimary(document);queueAccountSync();toast('Award display saved ✓')};
}

