async function showAdminGrant(direct=false){const level=await currentAdminLevel();if(level<1 || direct&&level<2)return;const users=list(await get('storeUsers',[])).filter(x=>x.status!=='disabled'),me=String(await get('userName','')),includeCreator=direct&&await currentIsCreator(),body=openModal(`<div class="modal-head"><div><div class="eyebrow">${direct?'ADMIN LEVEL 2':'AWARD NOMINATION'}</div><h2>${direct?'Directly Grant Award':'Nominate a User'}</h2></div><button class="close lkaw-close">×</button></div><div class="field"><label>LotKeys Store User</label><select id="lkaw-admin-user">${users.map(x=>`<option value="${esc(x.userName)}">${esc(x.profileDisplayName||x.userName)}</option>`).join('')}</select></div><div class="field"><label>Award</label><select id="lkaw-admin-award">${definitionOptions({includeCreator})}</select></div><div class="field"><label>Reason</label><textarea id="lkaw-admin-reason" maxlength="500" placeholder="Reason for this ${direct?'grant':'nomination'}…"></textarea></div><button class="btn primary block" id="lkaw-admin-submit" type="button">${direct?'Grant Award':'Submit Nomination'}</button>`);body.querySelector('#lkaw-admin-submit').onclick=async()=>{const target=body.querySelector('#lkaw-admin-user').value,awardId=body.querySelector('#lkaw-admin-award').value,reason=body.querySelector('#lkaw-admin-reason').value.trim();if(!reason)return toast('Add a reason for the award record.');const btn=body.querySelector('#lkaw-admin-submit');btn.disabled=true;btn.textContent='Saving…';try{if(direct){await grantStoreAward(target,awardId,uid('DIRECT'),{source:'Admin Level 2 direct grant',approvedBy:me,reason});toast('Award granted ✓')}else{const rows=list(await get(NOMINATIONS_KEY,[]));rows.push({id:uid('NOM'),kind:'admin-nomination',status:'pending',awardId,targetUserName:target,requestedByUserName:me,reason:reason.slice(0,500),createdAt:new Date().toISOString()});await set(NOMINATIONS_KEY,rows);await bridge()?.DriveSync?.syncStoreConfig?.();toast('Nomination sent for Admin Level 2 review ✓')}closeModal();scheduleDecorate()}catch(err){btn.disabled=false;btn.textContent=direct?'Grant Award':'Submit Nomination';alert(err.message||err)}}}

async function showReviewQueue(){if(await currentAdminLevel()<2)return;const rows=list(await get(NOMINATIONS_KEY,[])),pending=rows.filter(x=>x.status==='pending'),body=openModal(`<div class="modal-head"><div><div class="eyebrow">ADMIN LEVEL 2</div><h2>Award Review Queue</h2></div><button class="close lkaw-close">×</button></div><div class="lkaw-review-list">${pending.length?pending.map(x=>{const def=byId.get(x.awardId);return `<div class="lkaw-review-row" data-request-id="${esc(x.id)}"><img src="${esc(def?.image||'./assets/lotkeys-default-logo.png')}" alt=""><div><strong>${esc(x.targetUserName)} · ${esc(def?.name||x.awardId)}</strong><small>${esc(x.kind==='user-request'?'User request':'Admin nomination')} from ${esc(x.requestedByUserName||'LotKeys User')}</small><p>${esc(x.reason||'No reason supplied')}</p></div><div><button class="btn primary" data-lkaw-review="approved">Approve</button><button class="btn danger" data-lkaw-review="denied">Deny</button></div></div>`}).join(''):'<div class="empty">No award requests are waiting.</div>'}</div>`);body.querySelectorAll('[data-lkaw-review]').forEach(btn=>btn.onclick=async()=>{const row=btn.closest('[data-request-id]'),request=rows.find(x=>x.id===row.dataset.requestId),status=btn.dataset.lkawReview;if(!request)return;body.querySelectorAll('button').forEach(x=>x.disabled=true);try{if(status==='approved')await grantStoreAward(request.targetUserName,request.awardId,`request:${request.id}`,{source:request.kind==='user-request'?'Approved user request':'Approved Admin Level 1 nomination',approvedBy:await get('userName',''),reason:request.reason},false);request.status=status;request.resolvedAt=new Date().toISOString();request.resolvedByUserName=await get('userName','');await set(NOMINATIONS_KEY,rows);await bridge()?.DriveSync?.syncStoreConfig?.();toast(status==='approved'?'Award approved and granted ✓':'Award request denied');await showReviewQueue();scheduleDecorate()}catch(err){alert(err.message||err);await showReviewQueue()}})}

async function decoratePublicProfile(){const shell=document.querySelector('.public-profile-shell[data-lotkeys-user-name]');if(!shell||shell.dataset.lkawDecorated==='1')return;const users=list(await get('storeUsers',[])),user=users.find(x=>same(x.userName,shell.dataset.lotkeysUserName));if(!user)return;const entries=entriesFrom(user.awards?.length?user.awards:user.unlockedBadges),profileRaw=user.awardProfile||{primaryAwardId:user.primaryAwardId,displayAwardIds:user.displayAwardIds},valid=new Set(entries.map(x=>x.id)),primaryId=valid.has(profileRaw?.primaryAwardId)?profileRaw.primaryAwardId:(defFor(user.favoriteBadge)?.id||entries[0]?.id||''),display=list(profileRaw?.displayAwardIds).filter(x=>valid.has(x)&&x!==primaryId).slice(0,5);for(const e of entries)if(e.id!==primaryId&&!display.includes(e.id)&&display.length<5)display.push(e.id);const primary=entries.find(x=>x.id===primaryId),shown=display.map(id=>entries.find(x=>x.id===id)).filter(Boolean),old=shell.querySelector('details.account-edit-details'),box=document.createElement('div');box.className='lkaw-public-showcase';box.innerHTML=`<small>Primary Award</small>${primary?badgeButton(primary,{large:true,primary:true}):'<div class="help">No Primary Award selected.</div>'}<small>Displayed Awards</small><div class="lkaw-public-five">${shown.length?shown.map(x=>badgeButton(x)).join(''):'<div class="help">No public awards yet.</div>'}</div><button class="btn ghost block" type="button" id="lkaw-public-all" ${entries.length?'':'disabled'}>View All User Awards</button>`;old?.replaceWith(box);if(!old)shell.querySelector('.public-profile-tagline')?.after(box);shell.querySelector('.public-profile-level').textContent=`Lot-Lvl ${Math.max(1,Number(user.lotLevel)||1)} · ${Math.max(0,Number(user.confirmedFacebookPosts)||0)} confirmed posts`;box.querySelector('#lkaw-public-all')?.addEventListener('click',()=>showAllAwards(entries));bindBadgeButtons(box,entries);shell.dataset.lkawDecorated='1'}
function decorateInlinePrimary(root=document){root.querySelectorAll?.('.favorite-badge-inline:not([data-lkaw-inline])').forEach(el=>{const def=defFor(el.textContent.trim());if(!def)return;el.dataset.lkawInline='1';el.removeAttribute('title');el.innerHTML=`<img class="lkaw-inline-award" src="${esc(def.image)}" alt="" aria-hidden="true">`;if(el.parentNode&&el.parentNode.firstChild!==el)el.parentNode.insertBefore(el,el.parentNode.firstChild)})}

let decorating=false,decorateAgain=false;
async function decorate(){if(decorating){decorateAgain=true;return}decorating=true;try{decorateInlinePrimary(document);const title=String(document.getElementById('page-title')?.textContent||'');if(title==='Account')await renderProfileCard();if(title==='Garage')await renderGarageCard();await decoratePublicProfile()}catch(err){console.warn('Awards UI decoration deferred',err)}finally{decorating=false;if(decorateAgain){decorateAgain=false;scheduleDecorate()}}}
let decorateTimer=null;function scheduleDecorate(){clearTimeout(decorateTimer);decorateTimer=setTimeout(decorate,40)}
